// AccessSync post-purchase redirect — version {{VERSION}}
import wixLocationFrontend from 'wix-location-frontend';
import { currentMember } from 'wix-members-frontend';

const ACCESSSYNC_URL = '{{ADMIN_HUB_URL}}';
const CLIENT_ID = '{{CLIENT_ID}}';

$w.onReady(async function () {
  try {
    const member = await currentMember.getMember();
    if (!member?._id) return;
    wixLocationFrontend.to(
      ACCESSSYNC_URL + '/sync-status'
      + '?memberId=' + encodeURIComponent(member._id)
      + '&clientId=' + encodeURIComponent(CLIENT_ID)
    );
  } catch (e) {
    console.error('AccessSync redirect error:', e);
  }
});
